            Node("cycleWord_eq", "cycleWord_eq", "Literal source declaration. The appended lexical scope supplies the original parameters.", "@[simp] theorem cycleWord_eq (m : Nat) (hm : 3 ≤ m) :\n    cycleWord m hm =\n      (orderedFaces (pathIndependentOn (cyclePath m hm))).map\n        (fun T => .pair T (firstLabel m hm)) ++\n      (pathWord (cyclePathTail m hm)).map (adjoinSymbol (secondLabel m hm)) ++\n      (pathWord (cyclePathLast m hm)).map (adjoinSymbol (lastLabel m))", DescribeRole.Theorem, describeId: "cycle-word-eq"),
